// Device primitives: vector types, loads and stores with cache-policy bits, fp8 and MXFP4 MFMAs,
// wave and block reductions.
#pragma once

#include <hip/hip_runtime.h>

#include "common/hw.h"

namespace infera_flash {

using bfloat16 = __bf16; // not hip_bfloat16: it rounds in software, with a branch per value

using uint32x4 = uint32_t __attribute__((ext_vector_type(4)));
using int32x4  = int __attribute__((ext_vector_type(4)));
using int32x8  = int __attribute__((ext_vector_type(8)));
using floatx2  = float __attribute__((ext_vector_type(2)));
using floatx4  = float __attribute__((ext_vector_type(4)));

template <typename T, int N> __device__ inline void load_data(const T *src, T *dst) {
    static_assert(N * sizeof(T) == 16, "Only 16 bytes are supported.");
    *reinterpret_cast<uint4 *>(dst) = *reinterpret_cast<const uint4 *>(src);
}

template <typename T, int N> __device__ inline void store_data(T *dst, const T *src) {
    static_assert(N * sizeof(T) == 16, "Only 16 bytes are supported.");
    *reinterpret_cast<uint4 *>(dst) = *reinterpret_cast<const uint4 *>(src);
}

// sc1 sends a global access through the device-wide coherence point. Without it a store stays in
// this XCD's L2 and a load can keep hitting a stale L1 line, so other XCDs never see the value.
// s_nop 1: a VALU must not overwrite the store's data VGPRs for 2 wait states (ISA 4.5), and the
// compiler does not pad stores inside asm.
__device__ inline void store_sc1(uint32x4 *ptr, uint32x4 val) {
    asm volatile("global_store_dwordx4 %0, %1, off sc1\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}
__device__ inline void store_sc1(uint2 *ptr, uint2 val) {
    asm volatile("global_store_dwordx2 %0, %1, off sc1\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}
__device__ inline void store_sc1(uint32_t *ptr, uint32_t val) {
    asm volatile("global_store_dword %0, %1, off sc1\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}
__device__ inline void store_sc1(bfloat16 *ptr, bfloat16 val) {
    const uint32_t bits = __builtin_bit_cast(uint16_t, val);
    asm volatile("global_store_short %0, %1, off sc1\n\ts_nop 1" ::"v"(ptr), "v"(bits) : "memory");
}

// 16 B packets between blocks of one XCD: the store reaches their L2, an nt load reads it there
// past the CU cache (CDNA4 ISA, tables 49 and 50). asm store, so it is not merged or moved.
__device__ inline void store_l2(uint32x4 *ptr, uint32x4 val) {
    asm volatile("global_store_dwordx4 %0, %1, off\n\ts_nop 1" ::"v"(ptr), "v"(val) : "memory");
}
__device__ inline uint32x4 buffer_load_l2(__amdgpu_buffer_rsrc_t buffer, int offset) {
    constexpr int NT = 2; // the cache-policy operand's nt bit
    return __builtin_bit_cast(uint32x4,
                              __builtin_amdgcn_raw_buffer_load_b128(buffer, offset, 0, NT));
}

// Packets between GPUs, on uncached memory: system scope (sc0 sc1) and nt keep them out of every
// cache even where a mapping is cached. asm, so a polling loop really reloads.
__device__ inline void store_nt(uint32x4 *ptr, uint32x4 val) {
    asm volatile("global_store_dwordx4 %0, %1, off sc0 sc1 nt\n\ts_nop 1" ::"v"(ptr), "v"(val)
                 : "memory");
}

__device__ inline uint32x4 load_nt(const uint32x4 *ptr) {
    uint32x4 val;
    asm volatile("global_load_dwordx4 %0, %1, off sc0 sc1 nt\n\ts_waitcnt vmcnt(0)"
                 : "=v"(val)
                 : "v"(ptr)
                 : "memory");
    return val;
}

// Code that uses val stays after this point and memory accesses stay on their side of it: placed
// after later loads, it keeps the wait for val's load from holding them back.
template <typename T> __device__ inline void pin(T &val) {
    asm volatile("" : "+v"(val)::"memory");
}

// val as a value the compiler cannot see through, in a scalar register: loads whose address uses it
// go out from here, not hoisted with the loads before
__device__ inline int opaque(int val) {
    asm volatile("" : "+s"(val)::"memory");
    return val;
}

// __syncthreads also waits for every global load in flight; this waits for LDS accesses only.
__device__ inline void block_sync_lds() {
    asm volatile("s_waitcnt lgkmcnt(0)" ::: "memory");
    __builtin_amdgcn_s_barrier();
}

// A raw buffer resource over bytes [base, base + size), for loads with cache-policy bits.
__device__ inline __amdgpu_buffer_rsrc_t raw_buffer(const void *base, int size) {
    return __builtin_amdgcn_make_buffer_rsrc(const_cast<void *>(base), 0, size, 0x00020000);
}

// An sc1 load of a T (4, 8 or 16 B) at a byte offset, counted by the compiler like any load (an asm
// load is not: the compiler may move its register before the data lands).
template <typename T = uint32x4>
__device__ inline T buffer_load_sc1(__amdgpu_buffer_rsrc_t buffer, int offset) {
    constexpr int SC1 = 16; // the cache-policy operand's sc1 bit
    if constexpr (sizeof(T) == 4) {
        return __builtin_bit_cast(T, __builtin_amdgcn_raw_buffer_load_b32(buffer, offset, 0, SC1));
    } else if constexpr (sizeof(T) == 8) {
        return __builtin_bit_cast(T, __builtin_amdgcn_raw_buffer_load_b64(buffer, offset, 0, SC1));
    } else {
        static_assert(sizeof(T) == 16);
        return __builtin_bit_cast(T, __builtin_amdgcn_raw_buffer_load_b128(buffer, offset, 0, SC1));
    }
}

// Loads N consecutive 16-byte packets with sc1, waiting once for all of them.
template <int N> __device__ inline void load_sc1(const uint32x4 *ptr, uint32x4 (&vals)[N]) {
    static_assert(N == 1 || N == 2);
    if constexpr (N == 1) {
        asm volatile("global_load_dwordx4 %0, %1, off sc1\n\ts_waitcnt vmcnt(0)"
                     : "=v"(vals[0])
                     : "v"(ptr)
                     : "memory");
    } else {
        asm volatile("global_load_dwordx4 %0, %2, off sc1\n\t"
                     "global_load_dwordx4 %1, %2, off offset:16 sc1\n\t"
                     "s_waitcnt vmcnt(0)"
                     : "=&v"(vals[0]), "=&v"(vals[1])
                     : "v"(ptr)
                     : "memory");
    }
}

// One lane's 32 B of an fp8 MFMA 16x16x128 operand: K bytes 16g..16g+15 and 64+16g..64+16g+15 of
// row (A) or column (B) l % 16, for g = l / 16 (ISA layout).
__device__ inline int32x8 load_fragment(const uint8_t *first, const uint8_t *second) {
    const int32x4 lo = *reinterpret_cast<const int32x4 *>(first);
    const int32x4 hi = *reinterpret_cast<const int32x4 *>(second);
    return __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
}

// load_fragment with nt, for weights read once a layer: they stream through L2 and the MALL instead
// of pushing out what is read again (data read ahead for the next kernel, the lm_head between steps)
__device__ inline int32x8 load_fragment_nt(const uint8_t *first, const uint8_t *second) {
    const int32x4 lo = __builtin_nontemporal_load(reinterpret_cast<const int32x4 *>(first));
    const int32x4 hi = __builtin_nontemporal_load(reinterpret_cast<const int32x4 *>(second));
    return __builtin_shufflevector(lo, hi, 0, 1, 2, 3, 4, 5, 6, 7);
}

// D = A B for 16x16 fp8 e4m3 tiles over K = 128; lane l gets D[4 (l / 16) + i][l % 16] in element
// i. Zero scales make the compiler emit the instruction without block scaling.
__device__ inline floatx4 mfma_16x16x128_fp8(int32x8 a, int32x8 b) {
    return __builtin_amdgcn_mfma_scale_f32_16x16x128_f8f6f4(a, b, floatx4{}, 0, 0, 0, 0, 0, 0);
}

// C + A B for 16x16 MXFP4 (e2m1) tiles over K = 128, D laid out as fp8's. Lane l holds K
// 32 g..32 g + 31 (g = l / 16) of row (A) or column (B) l % 16, two per byte with the lower K in
// the low nibble, and that block's e8m0 scale in byte SEL of scale_a / scale_b (127 = 1.0). Half
// the cycles of fp8.
template <int SEL_A = 0, int SEL_B = 0>
__device__ inline floatx4 mfma_16x16x128_fp4(int32x4 a, int32x4 b, int scale_a, int scale_b,
                                             floatx4 c = {}) {
    constexpr int E2M1 = 4; // cbsz / blgp: the operand format
    // the builtin takes fp8's 8 VGPRs, fp4 reads the first 4: zero padding, as CK, which the
    // compiler drops
    const int32x8 a8 = {a[0], a[1], a[2], a[3], 0, 0, 0, 0};
    const int32x8 b8 = {b[0], b[1], b[2], b[3], 0, 0, 0, 0};
    return __builtin_amdgcn_mfma_scale_f32_16x16x128_f8f6f4(a8, b8, c, E2M1, E2M1, SEL_A, scale_a,
                                                            SEL_B, scale_b);
}

template <typename T> struct SumOp {
    __device__ static T op(const T &x, const T &y) { return x + y; }
};

template <typename T> struct MaxOp {
    __device__ static T op(const T &x, const T &y) { return x > y ? x : y; }
};

// Orders like the float, as an unsigned integer.
__device__ __forceinline__ uint32_t ordered_bits(float x) {
    const uint32_t bits = __float_as_uint(x);
    return (bits & 0x80000000u) ? ~bits : bits | 0x80000000u;
}

// Each lane gets the value of the lane that DPP_CTRL picks within its 16-lane row. bound_ctrl lets
// the compiler fold the move into the instruction that uses it.
template <int DPP_CTRL, typename T> __device__ inline T dpp_mov(T val) {
    static_assert(sizeof(T) == 4);
    return __builtin_bit_cast(
        T, __builtin_amdgcn_mov_dpp(__builtin_bit_cast(int, val), DPP_CTRL, 0xF, 0xF, true));
}

template <typename T> __device__ inline T readlane(T val, int lane) {
    static_assert(sizeof(T) == 4);
    return __builtin_bit_cast(T, __builtin_amdgcn_readlane(__builtin_bit_cast(int, val), lane));
}

// Reduces over each aligned group of WIDTH lanes; every lane gets its group's result. DPP within
// a 16-lane row; across rows, row 3 adds row 2 and then rows 0 + 1, and lane 63 is read out. No
// LDS round trip.
template <template <class> class Func, typename T, int WIDTH = THREADS_PER_WARP>
__device__ inline T WarpReduce(T val) {
    static_assert(WIDTH == 4 || WIDTH == 16 || WIDTH == THREADS_PER_WARP);
    val = Func<T>::op(dpp_mov<0xB1>(val), val); // quad_perm [1,0,3,2]
    val = Func<T>::op(dpp_mov<0x4E>(val), val); // quad_perm [2,3,0,1]
    if constexpr (WIDTH == 4) {
        return val;
    }
    val = Func<T>::op(dpp_mov<0x141>(val), val); // row_half_mirror
    val = Func<T>::op(dpp_mov<0x140>(val), val); // row_mirror
    if constexpr (WIDTH == THREADS_PER_WARP) {
        val = Func<T>::op(val, dpp_mov<0x142>(val)); // row_bcast:15, row r gets row r - 1
        val = Func<T>::op(val, dpp_mov<0x143>(val)); // row_bcast:31, rows 2, 3 get row 1
        val = readlane(val, 63);
    }
    return val;
}

// Every thread gets the result. Warps are combined in a fixed order so all blocks get the same
// bits. smem holds NUM_WARPS * N elements and can be reused as soon as this returns. LDS_ONLY
// syncs on LDS alone, leaving global loads in flight.
template <template <class> class Func, int BLOCK_SIZE, bool LDS_ONLY = false, typename T, int N>
__device__ inline void BlockReduce(T (&vals)[N], T *smem) {
    const auto sync = [] {
        if constexpr (LDS_ONLY) {
            block_sync_lds();
        } else {
            __syncthreads();
        }
    };
    constexpr int NUM_WARPS = BLOCK_SIZE / THREADS_PER_WARP;
    const int     warp_id   = threadIdx.x / THREADS_PER_WARP;
    const int     lane_id   = threadIdx.x % THREADS_PER_WARP;

#pragma unroll
    for (int n = 0; n < N; ++n) {
        vals[n] = WarpReduce<Func>(vals[n]);
    }
    // not inside the loop above: a branch there would serialize the N independent reductions
    if (lane_id == 0) {
#pragma unroll
        for (int n = 0; n < N; ++n) {
            smem[warp_id * N + n] = vals[n];
        }
    }
    sync();
#pragma unroll
    for (int n = 0; n < N; ++n) {
        vals[n] = smem[n];
#pragma unroll
        for (int w = 1; w < NUM_WARPS; ++w) {
            vals[n] = Func<T>::op(vals[n], smem[w * N + n]);
        }
    }
    sync();
}

} // namespace infera_flash

// fp8 or MXFP4 GEMM of up to 4 rows of x by an aiter-preshuffled weight, a 16-row group of the
// weight at a time.
#pragma once

#include <type_traits>

#include "common/device.h"
#include "common/hw.h"

namespace infera_flash {

// aiter-preshuffled weights come in groups of 16 rows; a group's 128-K block is a contiguous 2 KB
// (MXFP4: 1 KB, lane l of the fp4 MFMA reading its 16 B at 16 l)
constexpr int K_BLOCK_BYTES = 16 * 128;
// by format: that block's bytes, and a lane's share of it for the MFMA
template <bool MXFP4> constexpr int K_BLOCK_BYTES_OF = MXFP4 ? K_BLOCK_BYTES / 2 : K_BLOCK_BYTES;
template <bool MXFP4> using Fragment = std::conditional_t<MXFP4, int32x4, int32x8>;

// The dword of aiter's shuffle_scale layout holding the e8m0 of (row, group) of [rows, GROUPS]
// MXFP4 scales: it packs rows r, r + 16 of groups g, g + 4 (r % 32 < 16, g % 8 < 4), this one at
// byte group / 4 % 2 * 2 + row / 16 % 2. Returns its byte offset.
template <int GROUPS> __device__ inline int e8m0_dword(int row, int group) {
    return row / 32 * 32 * GROUPS + group / 8 * 256 + group % 4 * 64 + row % 16 * 4;
}

// What a wave of group_out needs of 16-row group `group` of a preshuffled [rows, K] fp8 weight: its
// quarter of the K blocks, and in lane j the scale of its K block j. The scales go out first.
template <int K>
__device__ __forceinline__ void load_group(const uint8_t *weight, const float *scale, int group,
                                           int32x8 (&w)[K / 128 / WAVES], float &w_scales) {
    constexpr int WAVE_K = K / 128 / WAVES;
    const int     lane   = threadIdx.x % THREADS_PER_WARP;
    const int     kb0    = threadIdx.x / THREADS_PER_WARP * WAVE_K;
    w_scales             = scale[group / 8 * (K / 128) + kb0 + lane % WAVE_K];
    const uint8_t *src = weight + static_cast<size_t>(group) * 16 * K + kb0 * K_BLOCK_BYTES +
                         lane / 16 * 256 + lane % 16 * 16;
#pragma unroll
    for (int j = 0; j < WAVE_K; ++j) {
        w[j] = load_fragment(src + j * K_BLOCK_BYTES, src + j * K_BLOCK_BYTES + 1024);
    }
}

// load_group for an MXFP4 weight (e2m1 pairs) and its e8m0 in aiter shuffle_scale's layout: lane
// l's 16 B of each of its wave's K blocks, and a dword per two blocks holding their scales of its
// row l % 16 and K 32 (l / 16) on (e8m0_dword: bytes 0 and 2 once shifted right by group % 2 * 8).
template <int K>
__device__ __forceinline__ void load_group_mxfp4(const uint8_t *weight, const uint8_t *scale,
                                                 int group, int32x4 (&w)[K / 128 / WAVES],
                                                 int (&w_e8m0)[K / 128 / WAVES / 2]) {
    constexpr int WAVE_K = K / 128 / WAVES;
    const int     lane   = threadIdx.x % THREADS_PER_WARP;
    const int     kb0    = threadIdx.x / THREADS_PER_WARP * WAVE_K;
    static_assert(WAVE_K % 2 == 0);
#pragma unroll
    for (int p = 0; p < WAVE_K / 2; ++p) {
        w_e8m0[p] = *reinterpret_cast<const int *>(
            scale + e8m0_dword<K / 32>(group * 16 + lane % 16, 4 * (kb0 + 2 * p) + lane / 16));
    }
    const uint8_t *src = weight + static_cast<size_t>(group) * 8 * K +
                         kb0 * K_BLOCK_BYTES_OF<true> + lane * 16;
#pragma unroll
    for (int j = 0; j < WAVE_K; ++j) {
        w[j] = *reinterpret_cast<const int32x4 *>(src + j * K_BLOCK_BYTES_OF<true>);
    }
}

// LDS of group_store, for up to MAX_TOKENS rows of x
template <int MAX_TOKENS>
struct GroupSmem {
    floatx4  tiles[Hw::BLOCK_SIZE];   // each wave's 16x16 partial sum
    bfloat16 out[MAX_TOKENS * 16]; // the group's outputs, [M][16]
};

// The group's [M][16] outputs from each wave's 16x16 partial sum acc: the 4 added in wave order,
// rounded to bf16 and stored 16 B per half row at out (row stride `stride`), with sc1 when other
// XCDs read them back.
template <int NUM_TOKENS, bool SC1, int MAX_TOKENS>
__device__ __forceinline__ void group_store(floatx4 acc, GroupSmem<MAX_TOKENS> &s, bfloat16 *out,
                                            int stride) {
    static_assert(NUM_TOKENS <= MAX_TOKENS);
    const int tid = threadIdx.x;
    s.tiles[tid]  = acc;
    block_sync_lds();
    // thread (m, r): row r of token m, at lane 16 (r / 4) + m of each wave's tile, element r % 4
    if (tid < 16 * NUM_TOKENS) {
        const floatx4 *tile = s.tiles + 16 * (tid % 16 / 4) + tid / 16;
        float          sum  = 0.0f;
#pragma unroll
        for (int v = 0; v < WAVES; ++v) {
            sum += tile[v * THREADS_PER_WARP][tid % 4];
        }
        s.out[tid] = static_cast<bfloat16>(sum);
    }
    block_sync_lds();
    if (tid < 2 * NUM_TOKENS) {
        const uint32x4 val = reinterpret_cast<const uint32x4 *>(s.out)[tid];
        auto          *dst = reinterpret_cast<uint32x4 *>(out + tid / 2 * stride + tid % 2 * 8);
        if constexpr (SC1) {
            store_sc1(dst, val);
        } else {
            *dst = val;
        }
    }
}

// A wave's sum over N fp8 K blocks from kb0: w and, in lane j, the scale of block kb0 + j as
// load_group loads them; x [M][K] in LDS with its scales [M][K / 128], this lane's column token.
template <int K, int N>
__device__ __forceinline__ floatx4 fp8_blocks(const int32x8 (&w)[N], float w_scales,
                                              const uint8_t *x, const float *x_scale, int token,
                                              int kb0) {
    const int lane = threadIdx.x % THREADS_PER_WARP;
    floatx4   acc  = {};
#pragma unroll
    for (int j = 0; j < N; ++j) {
        const uint8_t *xq = x + token * K + (kb0 + j) * 128 + lane / 16 * 16;
        acc += mfma_16x16x128_fp8(w[j], load_fragment(xq, xq + 64)) *
               (readlane(w_scales, j) * x_scale[token * (K / 128) + kb0 + j]);
    }
    return acc;
}

// The group's [M][16] outputs (group_store) from the fp8 x [M][K] in LDS (scales [M][K / 128]):
// each wave's partial sum over its K blocks.
template <int K, int NUM_TOKENS, bool SC1, int MAX_TOKENS>
__device__ __forceinline__ void group_out(const int32x8 (&w)[K / 128 / WAVES], float w_scales,
                                          const uint8_t *x, const float *x_scale,
                                          GroupSmem<MAX_TOKENS> &s, bfloat16 *out, int stride) {
    constexpr int WAVE_K = K / 128 / WAVES;
    const int     lane   = threadIdx.x % THREADS_PER_WARP;
    // columns past M repeat token M - 1 and are dropped
    const floatx4 acc = fp8_blocks<K, WAVE_K>(w, w_scales, x, x_scale,
                                              min(lane % 16, NUM_TOKENS - 1),
                                              threadIdx.x / THREADS_PER_WARP * WAVE_K);
    group_store<NUM_TOKENS, SC1>(acc, s, out, stride);
}

// A wave's sum over N MXFP4 K blocks from kb0 (even: block pairs share a dword): w and w_e8m0 as
// load_group_mxfp4 loads them (the e8m0 at bytes 0 and 2 once shifted right by `shift`), x
// [M][K / 2] in LDS with its e8m0 [M][K / 32], this lane's column token. The scales go into the
// instruction, which accumulates.
template <int K, int N>
__device__ __forceinline__ floatx4 mxfp4_blocks(const int32x4 (&w)[N], const int (&w_e8m0)[N / 2],
                                                int shift, const uint8_t *x, const uint8_t *x_e8m0,
                                                int token, int kb0) {
    static_assert(N % 2 == 0);
    const int  lane = threadIdx.x % THREADS_PER_WARP;
    const auto x_of = [&](int b) {
        return *reinterpret_cast<const int32x4 *>(x + token * K / 2 + b * 64 + lane / 16 * 16);
    };
    const auto e_of = [&](int b) { return x_e8m0[token * K / 32 + 4 * b + lane / 16]; };
    floatx4    acc  = {};
#pragma unroll
    for (int i = 0; i < N / 2; ++i) {
        const int b       = kb0 + 2 * i;
        const int w_scale = w_e8m0[i] >> shift;
        acc = mfma_16x16x128_fp4<0, 0>(w[2 * i], x_of(b), w_scale, e_of(b), acc);
        acc = mfma_16x16x128_fp4<2, 0>(w[2 * i + 1], x_of(b + 1), w_scale, e_of(b + 1), acc);
    }
    return acc;
}

// group_out for group `group` of an MXFP4 weight (load_group_mxfp4) and x [M][K / 2] in LDS with
// its e8m0 [M][K / 32].
template <int K, int NUM_TOKENS, bool SC1, int MAX_TOKENS>
__device__ __forceinline__ void group_out_mxfp4(const int32x4 (&w)[K / 128 / WAVES],
                                                const int (&w_e8m0)[K / 128 / WAVES / 2], int group,
                                                const uint8_t *x, const uint8_t *x_e8m0,
                                                GroupSmem<MAX_TOKENS> &s, bfloat16 *out,
                                                int stride) {
    constexpr int WAVE_K = K / 128 / WAVES;
    const int     lane   = threadIdx.x % THREADS_PER_WARP;
    // columns past M repeat token M - 1 and are dropped
    const floatx4 acc = mxfp4_blocks<K, WAVE_K>(w, w_e8m0, group % 2 * 8, x, x_e8m0,
                                                min(lane % 16, NUM_TOKENS - 1),
                                                threadIdx.x / THREADS_PER_WARP * WAVE_K);
    group_store<NUM_TOKENS, SC1>(acc, s, out, stride);
}

} // namespace infera_flash

// MI355X as our kernels use it: block b runs on XCD b % NUM_XCDS, and a kernel whose blocks wait on
// each other runs NUM_BLOCKS of them, all resident.
#pragma once

namespace infera_flash {

constexpr int THREADS_PER_WARP = 64;

struct Hw {
    static constexpr int NUM_BLOCKS = 256; // one per CU
    static constexpr int NUM_XCDS   = 8;
    static constexpr int BLOCK_SIZE = 256;
    // all of a CU's LDS, so each CU runs exactly one block
    static constexpr int SMEM_SIZE = 160 * 1024;
};

constexpr int WAVES = Hw::BLOCK_SIZE / THREADS_PER_WARP; // a block's

} // namespace infera_flash

// Math the kernels share, rounded as HF rounds: bf16 pairs, fp8 conversion and quant, MXFP4 quant
// (as Quark), RoPE, the residual add and RMSNorm.
#pragma once

#include "common/device.h"
#include "common/hw.h"

namespace infera_flash {

using bfloat16x2 = bfloat16 __attribute__((ext_vector_type(2)));

// bf16 pairs to floats (exact) and back (round to nearest even), for packed floatx2 math
__device__ inline floatx2 to_float2(bfloat16x2 v) { return __builtin_convertvector(v, floatx2); }
__device__ inline bfloat16x2 to_bf16x2(floatx2 v) { return __builtin_convertvector(v, bfloat16x2); }

constexpr float FP8_MAX = 448.0f; // largest finite e4m3fn

using bfloat16x8 = bfloat16 __attribute__((ext_vector_type(8)));

// 8 fp8 values as bf16, exactly, 2 per instruction
__device__ inline bfloat16x8 fp8x8_to_bf16(uint32_t lo, uint32_t hi) {
    const bfloat16x2 v0 = __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(lo, 1.0f, false);
    const bfloat16x2 v1 = __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(lo, 1.0f, true);
    const bfloat16x2 v2 = __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(hi, 1.0f, false);
    const bfloat16x2 v3 = __builtin_amdgcn_cvt_scalef32_pk_bf16_fp8(hi, 1.0f, true);
    return __builtin_shufflevector(__builtin_shufflevector(v0, v1, 0, 1, 2, 3),
                                   __builtin_shufflevector(v2, v3, 0, 1, 2, 3), 0, 1, 2, 3, 4, 5, 6,
                                   7);
}

// aiter's MXFP4 quant (MxScaleRoundMode RoundUp, its default) of a 32-value group held by 4
// consecutive lanes, 8 values each: stores this lane's 8 e2m1 codes (4 B, the lower K in the low
// nibble) to q and returns the group's e8m0 scale, 2^(e8m0 - 127), amax / 6 rounded up to a power
// of two; values round to nearest even.
__device__ inline int quant_mxfp4(const bfloat16 (&x)[8], uint8_t *q) {
    float amax = 0.0f;
#pragma unroll
    for (int j = 0; j < 8; ++j) {
        amax = fmaxf(amax, fabsf(static_cast<float>(x[j])));
    }
    amax = __uint_as_float(WarpReduce<MaxOp, uint32_t, 4>(__float_as_uint(amax)));
    const uint32_t ratio = __float_as_uint(amax / 6.0f);
    const int      e8m0  = min(static_cast<int>((ratio >> 23) + ((ratio & 0x7fffffu) != 0u)), 254);
    // the convert divides by scale; its byte index must be a constant, so one call per byte
    const float scale = __uint_as_float(static_cast<uint32_t>(e8m0) << 23);
    const auto  f     = [&](int j) { return static_cast<float>(x[j]); };
    uint32_t    codes = __builtin_amdgcn_cvt_scalef32_pk_fp4_f32(0, f(0), f(1), scale, 0);
    codes             = __builtin_amdgcn_cvt_scalef32_pk_fp4_f32(codes, f(2), f(3), scale, 1);
    codes             = __builtin_amdgcn_cvt_scalef32_pk_fp4_f32(codes, f(4), f(5), scale, 2);
    codes             = __builtin_amdgcn_cvt_scalef32_pk_fp4_f32(codes, f(6), f(7), scale, 3);
    *reinterpret_cast<uint32_t *>(q) = codes;
    return e8m0;
}

// HF's interleaved RoPE of the pair (x0, x1) by the position's (c, s), each bf16 op rounded: an
// FMA would skip the products' rounding
__device__ inline void rope_pair(float &x0, float &x1, float c, float s) {
#pragma clang fp contract(off)
    const auto  bf16 = [](float v) { return static_cast<float>(static_cast<bfloat16>(v)); };
    const float y0   = bf16(bf16(x0 * c) - bf16(x1 * s));
    x1               = bf16(bf16(x1 * c) + bf16(x0 * s));
    x0               = y0;
}

// HF finegrained-fp8 quant of a 1x128 group held by 16 consecutive lanes, 8 values each: stores
// this lane's 8 fp8 values to q and returns the group's scale. A multiply and v_rcp where HF
// divides move a few values by one fp8 step.
__device__ inline float quant_fp8(const bfloat16 (&x)[8], uint8_t *q) {
    const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x);
    floatx2     v[4];
    float       amax = 0.0f;
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        v[j] = to_float2(x2[j]); // pairs, so a scale_row before stays packed
        amax = fmaxf(amax, fmaxf(fabsf(v[j].x), fabsf(v[j].y)));
    }
    // amax >= 0 orders like its bits: an integer max, whose DPP moves fold into it
    amax = __uint_as_float(WarpReduce<MaxOp, uint32_t, 16>(__float_as_uint(amax)));
    const float scale     = amax * (1.0f / FP8_MAX);
    const float inv_scale = __builtin_amdgcn_rcpf(fmaxf(scale, 1e-12f));
    uint32_t    fp8[2];
#pragma unroll
    for (int j = 0; j < 2; ++j) {
        const floatx2 lo = v[2 * j] * inv_scale; // packed: two values per instruction
        const floatx2 hi = v[2 * j + 1] * inv_scale;
        // the second convert overwrites the half the first keeps: no need to zero it
        const int any    = __builtin_bit_cast(int, lo.x);
        fp8[j]           = __builtin_amdgcn_cvt_pk_fp8_f32(
            hi.x, hi.y, __builtin_amdgcn_cvt_pk_fp8_f32(lo.x, lo.y, any, false), true);
    }
    *reinterpret_cast<uint2 *>(q) = *reinterpret_cast<const uint2 *>(fp8);
    return scale;
}

// x's rows quantized into LDS, each thread holding LOADS x 8 values of every row (as rms_norm's
// x): fp8 as HF, scales [M][COLS / 128], or MXFP4 as aiter, e8m0 [M][COLS / 32]
template <int NUM_TOKENS, int LOADS, bool MXFP4>
__device__ __forceinline__ void quant_rows(const bfloat16 (&x)[NUM_TOKENS][LOADS][8], uint8_t *q,
                                           void *scales) {
    constexpr int COLS   = LOADS * 8 * Hw::BLOCK_SIZE;
    const int     tid    = threadIdx.x;
    const auto    offset = [&](int m, int i) { return m * COLS + (i * Hw::BLOCK_SIZE + tid) * 8; };
    if constexpr (MXFP4) {
        int e8m0[NUM_TOKENS][LOADS];
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < LOADS; ++i) {
                e8m0[m][i] = quant_mxfp4(x[m][i], q + offset(m, i) / 2);
            }
        }
        // not inside the loop above: a branch there would serialize the groups
        if (tid % 4 == 0) {
#pragma unroll
            for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
                for (int i = 0; i < LOADS; ++i) {
                    static_cast<uint8_t *>(scales)[offset(m, i) / 32] = e8m0[m][i];
                }
            }
        }
    } else {
        float s[NUM_TOKENS][LOADS];
#pragma unroll
        for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
            for (int i = 0; i < LOADS; ++i) {
                s[m][i] = quant_fp8(x[m][i], q + offset(m, i));
            }
        }
        if (tid % 16 == 0) {
#pragma unroll
            for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
                for (int i = 0; i < LOADS; ++i) {
                    static_cast<float *>(scales)[offset(m, i) / 128] = s[m][i];
                }
            }
        }
    }
}

// HF's act_fn(gate) * up of the linears' bf16 outputs: silu and the product each round to bf16
__device__ __forceinline__ bfloat16 silu_mul(bfloat16 gate, bfloat16 up) {
    const float g    = gate;
    const float silu = static_cast<bfloat16>(g / (1.0f + expf(-g)));
    return static_cast<bfloat16>(silu * static_cast<float>(up));
}

// x += residual as HF adds them, in bf16; each thread holds LOADS x 8 values of every row.
template <int NUM_TOKENS, int LOADS>
__device__ __forceinline__ void add_rows(bfloat16 (&x)[NUM_TOKENS][LOADS][8],
                                         const bfloat16 (&residual)[NUM_TOKENS][LOADS][8]) {
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            auto       *x2 = reinterpret_cast<bfloat16x2 *>(x[m][i]);
            const auto *r2 = reinterpret_cast<const bfloat16x2 *>(residual[m][i]);
#pragma unroll
            for (int j = 0; j < 4; ++j) {
                x2[j] = to_bf16x2(to_float2(x2[j]) + to_float2(r2[j]));
            }
        }
    }
}

// sum2 += x^2 over 8 values, two at a time
__device__ __forceinline__ void add_squares(floatx2 &sum2, const bfloat16 (&x)[8]) {
    const auto *x2 = reinterpret_cast<const bfloat16x2 *>(x);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        const floatx2 v = to_float2(x2[j]);
        sum2 += v * v;
    }
}

// v as computed, in VGPRs: the compiler would split a pair whose halves are used apart into one
// convert and one multiply per value
template <typename T> __device__ __forceinline__ void keep_pair(T &v) {
    asm volatile("" : "+v"(v));
}

// 8 values of a row as HF's RMSNorm leaves them: x = bf16(gamma * bf16(x * factor)), gamma in
// float pairs
__device__ __forceinline__ void scale_row(bfloat16 (&x)[8], const floatx2 (&gamma)[4],
                                          float factor) {
    auto *x2 = reinterpret_cast<bfloat16x2 *>(x);
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        const floatx2 normed = to_float2(to_bf16x2(to_float2(x2[j]) * factor));
        x2[j]                = to_bf16x2(gamma[j] * normed);
        keep_pair(x2[j]);
    }
}

__device__ __forceinline__ void scale_row(bfloat16 (&x)[8], const bfloat16 (&gamma)[8],
                                          float factor) {
    const auto *g2 = reinterpret_cast<const bfloat16x2 *>(gamma);
    floatx2     g[4];
#pragma unroll
    for (int j = 0; j < 4; ++j) {
        g[j] = to_float2(g2[j]);
    }
    scale_row(x, g, factor);
}

// HF's RMSNorm of M rows, each thread holding LOADS x 8 values of every row (so rows of LOADS x 8 x
// BLOCK_SIZE). LDS_ONLY as BlockReduce's.
template <int NUM_TOKENS, int LOADS, bool LDS_ONLY>
__device__ __forceinline__ void rms_norm(bfloat16 (&x)[NUM_TOKENS][LOADS][8],
                                         const bfloat16 (&gamma)[LOADS][8], float eps,
                                         float *reduce) {
    constexpr int COLS = LOADS * 8 * Hw::BLOCK_SIZE;
    float sums[NUM_TOKENS];
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        floatx2 sum2 = {};
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            add_squares(sum2, x[m][i]);
        }
        sums[m] = sum2.x + sum2.y;
    }
    BlockReduce<SumOp, Hw::BLOCK_SIZE, LDS_ONLY>(sums, reduce);
    floatx2 g[LOADS][4]; // once for all rows
#pragma unroll
    for (int i = 0; i < LOADS; ++i) {
#pragma unroll
        for (int j = 0; j < 4; ++j) {
            g[i][j] = to_float2(reinterpret_cast<const bfloat16x2 *>(gamma[i])[j]);
            keep_pair(g[i][j]);
        }
    }
#pragma unroll
    for (int m = 0; m < NUM_TOKENS; ++m) {
        // torch's mean multiplies by 1/N rather than dividing
        const float factor = rsqrtf(sums[m] * (1.0f / COLS) + eps);
#pragma unroll
        for (int i = 0; i < LOADS; ++i) {
            scale_row(x[m][i], g[i], factor);
        }
    }
}

