namespace infera_flash::glm5 {

// mlp_gate_up (mlp.h)
template <int NUM_TOKENS, bool MXFP4>
__global__ __launch_bounds__(Config::BLOCK_SIZE) __attribute__((amdgpu_waves_per_eu(1, 1))) void
mlp_gate_up_kernel(const MlpGateUpParams p) {
    extern __shared__ __align__(16) uint8_t smem[];
    uint32x4 *slots = static_cast<uint32x4 *>(p.workspace);
    mlp::mlp_gate_up_block<NUM_TOKENS, MXFP4>(p, smem, slots,
                                              next_epoch(slots + blockIdx.x * PACKETS_PER_SLOT));
}

void mlp_gate_up_launch(const MlpGateUpParams &params, int num_tokens, hipStream_t stream) {
    static void (*const kernels[2][Config::MAX_NUM_TOKENS])(MlpGateUpParams) = {
        {mlp_gate_up_kernel<1, false>, mlp_gate_up_kernel<2, false>, mlp_gate_up_kernel<3, false>,
         mlp_gate_up_kernel<4, false>},
        {mlp_gate_up_kernel<1, true>, mlp_gate_up_kernel<2, true>, mlp_gate_up_kernel<3, true>,
         mlp_gate_up_kernel<4, true>}};
    const auto kernel = kernels[params.mxfp4][num_tokens - 1];
    // all of a CU's LDS, as moe: one block per CU, all resident for the exchange
    kernel<<<Config::NUM_BLOCKS, Config::BLOCK_SIZE, Config::SMEM_SIZE, stream>>>(params);
    C10_HIP_CHECK(hipGetLastError());
}

template <int K, int NUM_TOKENS, bool MXFP4>
__global__ __launch_bounds__(Config::BLOCK_SIZE) __attribute__((amdgpu_waves_per_eu(1, 1))) void
row_linear_ar_kernel(const RowLinearParams p) {
    extern __shared__ __align__(16) uint8_t smem[];
    row_linear_ar_block<K, NUM_TOKENS, false, MXFP4>(p, smem, last_call(p.ar));
}

void row_linear_ar_launch(const RowLinearParams &params, int num_tokens, int k,
                          hipStream_t stream) {
#define KERNELS(K, MXFP4)                                                                          \
    {row_linear_ar_kernel<K, 1, MXFP4>, row_linear_ar_kernel<K, 2, MXFP4>,                        \
     row_linear_ar_kernel<K, 3, MXFP4>, row_linear_ar_kernel<K, 4, MXFP4>}
    // [the dense down, fp8 or MXFP4; o_proj, fp8][M - 1]
    static void (*const kernels[3][Config::MAX_NUM_TOKENS])(RowLinearParams) = {
        KERNELS(Config::DENSE_ROWS, false), KERNELS(Config::DENSE_ROWS, true),
        KERNELS(Config::O_PROJ_K, false)};
#undef KERNELS
    const auto kernel = kernels[k == Config::O_PROJ_K ? 2 : params.mxfp4][num_tokens - 1];
    // all of a CU's LDS, as moe: one block per CU
    kernel<<<Config::NUM_BLOCKS, Config::BLOCK_SIZE, Config::SMEM_SIZE, stream>>>(params);
    C10_HIP_CHECK(hipGetLastError());
}

