// GLM-5's dense layers after their attention on one TP8 rank for M <= 4 tokens, fp8 weights at a
// scale per 128 x 128 block (GLM-5.3-FP8): post_attention_layernorm, then silu(gate) * up on its
// output quantized per 1 x 128 (Infera-Flash's mlp_gate_up), then down on that quantized the same
// way, summed over the ranks of the peer memory in rank order and added to the stream
// (row_linear_ar).
// source: Infera-Flash csrc/glm5 at 3b1dc45
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <ATen/hip/impl/HIPGuardImplMasqueradingAsCUDA.h>
