namespace {

// mlp_gate_up's sync slots, then row_linear_ar's call number per block
constexpr int64_t STATE_BYTES = WORKSPACE_SIZE + Config::NUM_BLOCKS * sizeof(int);

void run(const at::Tensor &hidden_states, const at::Tensor &norm_weight, double norm_eps,
         const at::Tensor &gate_up_weight, const at::Tensor &gate_up_scale,
         const at::Tensor &down_weight, const at::Tensor &down_scale,
         std::optional<at::ScalarType> out_dtype, at::Tensor &out, at::Tensor &state,
         const at::Tensor &peers, int64_t rank) {
    const int64_t num_tokens = hidden_states.size(0);
    TORCH_CHECK(num_tokens >= 1 && num_tokens <= Config::MAX_NUM_TOKENS, "1 to ",
                Config::MAX_NUM_TOKENS, " tokens");
    // zeroed once and kept: each call counts its epoch and call number on from the last one's
    TORCH_CHECK(state.nbytes() >= STATE_BYTES, "state: ", STATE_BYTES, " bytes");
    // the receive buffers' addresses, read here on the host
    TORCH_CHECK(peers.device().is_cpu() && peers.scalar_type() == at::kLong && peers.dim() == 1 &&
                    peers.numel() >= 1 && peers.numel() <= Config::MAX_RANKS && rank >= 0 &&
                    rank < peers.numel(),
                "peers: every rank's peer memory, int64 on the host, 1 to ", Config::MAX_RANKS);
    const at::hip::OptionalHIPGuardMasqueradingAsCUDA guard(hidden_states.device());
    // the blocks wait on each other: all of them must be resident
    int cus = 0;
    C10_HIP_CHECK(hipDeviceGetAttribute(&cus, hipDeviceAttributeMultiprocessorCount,
                                        hidden_states.get_device()));
    TORCH_CHECK(cus == Config::NUM_BLOCKS, "needs all ", Config::NUM_BLOCKS,
                " CUs of an MI355X (no partitions)");
    const hipStream_t stream = at::hip::getCurrentHIPStream();
    at::Tensor act  = at::empty({num_tokens, Config::DENSE_ROWS}, hidden_states.options());
    at::Tensor gate = at::empty({num_tokens, Config::DENSE_ROWS}, hidden_states.options());
    // gate_up's rows: gate_proj's, then up_proj's, each a whole number of shuffle_weight's 16-row
    // tiles and of the scales' 128-row blocks
    const auto *weight = static_cast<const uint8_t *>(gate_up_weight.data_ptr());
    const auto *scale  = gate_up_scale.data_ptr<float>();
    MlpGateUpParams up{};
    up.x           = static_cast<const bfloat16 *>(hidden_states.data_ptr());
    up.gamma       = static_cast<const bfloat16 *>(norm_weight.data_ptr());
    up.epsilon     = static_cast<float>(norm_eps);
    up.mxfp4       = false;
    up.gate_weight = weight;
    up.gate_scale  = scale;
    up.up_weight   = weight + static_cast<size_t>(Config::DENSE_ROWS) * Config::HIDDEN_SIZE;
    up.up_scale    = scale + Config::DENSE_ROWS / 128 * Config::NUM_GROUPS;
    up.workspace   = state.data_ptr();
    up.act         = static_cast<bfloat16 *>(act.data_ptr());
    up.gate        = static_cast<bfloat16 *>(gate.data_ptr());
    mlp_gate_up_launch(up, static_cast<int>(num_tokens), stream);
    RowLinearParams down{};
    down.x              = up.act;
    down.mxfp4          = false;
    down.weight         = static_cast<const uint8_t *>(down_weight.data_ptr());
    down.weight_scale   = down_scale.data_ptr();
    AllReduceParams &ar = down.ar;
    ar.out              = static_cast<bfloat16 *>(out.data_ptr());
    ar.accumulate       = true;
    ar.prior            = up.x;
    ar.world            = static_cast<int>(peers.numel());
    ar.rank             = static_cast<int>(rank);
    ar.calls = reinterpret_cast<int *>(static_cast<uint8_t *>(state.data_ptr()) + WORKSPACE_SIZE);
    for (int r = 0; r < ar.world; ++r) {
        ar.recv[r] = reinterpret_cast<void *>(peers.data_ptr<int64_t>()[r]);
    }
    row_linear_ar_launch(down, static_cast<int>(num_tokens), Config::DENSE_ROWS, stream);
}

} // namespace
} // namespace infera_flash::glm5

#define TORCH_LIBRARY_EXPAND(ns, m) TORCH_LIBRARY(ns, m)
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, m) {
    m.def("run(Tensor hidden_states, Tensor norm_weight, float norm_eps, Tensor gate_up_weight, "
          "Tensor gate_up_scale, Tensor down_weight, Tensor down_scale, ScalarType? out_dtype, "
          "Tensor(a!) out, Tensor(b!) state, Tensor peers, int rank) -> ()",
          &infera_flash::glm5::run);
}
